package com.purchasing.repository; import com.purchasing.entity.PurchaseOrder; import org.springframework.data.jpa.repository.*; import java.util.*; public interface PurchaseOrderRepository extends JpaRepository<PurchaseOrder,Long>{ @Query("select coalesce(sum(p.quantity),0) from PurchaseOrder p where p.product.id=:productId and p.status in ('OPEN','CREATED','VALIDATED')") Integer openQuantity(Long productId); }
